package com.grifplot.libros;
import java.net.*;
public class BrowserPricesTest {
 static void check(boolean yes,String name){if(!yes)throw new AssertionError(name);System.out.println("OK "+name);}
 public static void main(String[] args)throws Exception {String query="Álgebra UNHEVAL 2025 & autor";String url=BrowserRules.google(query,false);check(URLDecoder.decode(url.substring(url.indexOf("q=")+2,url.indexOf("&hl=")),"UTF-8").equals(query),"Google conserva consulta con tildes y signos");check(URLDecoder.decode(BrowserRules.google(query,true),"UTF-8").contains(query+" filetype:pdf"),"filtro PDF opcional");check(BrowserRules.pdf("https://site.test/Libro.PDF?download=1"),"PDF con parámetros");check(!BrowserRules.pdf("https://site.test/resultado?url=Libro.pdf"),"HTML no identificado como PDF por parámetro");check(!BrowserRules.web("javascript:alert(1)"),"esquema JavaScript rechazado");check(!BrowserRules.web("file:///private.pdf"),"archivos privados no navegables");check(PrintPrices.valid("12,50").equals("12.50"),"precio con coma");check(PrintPrices.valid("0").equals("0.00"),"precio gratuito explícito");check(PrintPrices.valid("").isEmpty(),"precio pendiente no se inventa");check(PrintPrices.display("","S/").equals("Consultar precio"),"libro sin precio permitido con importe por consultar");check(PrintPrices.display("25","S/").equals("S/ 25.00"),"precio fijo del libro completo");boolean bad=false;try{PrintPrices.valid("-2");}catch(Exception e){bad=true;}check(bad,"precio negativo rechazado");bad=false;try{PrintPrices.valid("2.123");}catch(Exception e){bad=true;}check(bad,"máximo dos decimales");}
}
